function h($v):string{return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}function j($v):string{return json_encode($v,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT|JSON_THROW_ON_ERROR);}function n($v):string{return is_numeric($v)?((abs($v)>0&&abs($v)<.0001)||abs($v)>=1e6?sprintf('%.5e',$v):rtrim(rtrim(sprintf('%.6f',$v),'0'),'.')):(string)$v;}
function security():void{header_remove('X-Powered-By');if(($_SERVER['REQUEST_METHOD']??'GET')==='POST')header('Cache-Control: no-store');header('X-Content-Type-Options: nosniff');header('Referrer-Policy: strict-origin-when-cross-origin');header('X-Frame-Options: DENY');header("Content-Security-Policy: default-src 'self'; script-src 'self'; style-src 'self'; img-src 'self'; connect-src 'self'; object-src 'none'; base-uri 'none'; frame-src 'none'; frame-ancestors 'none'; form-action 'self'");}
function start(string $title,string $desc,string $path,bool $noindex=false):void{security();$url=BASE.$path;if($noindex)header('X-Robots-Tag: noindex');?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title><?=h($title)?> | Beyond Spacetime</title><meta name="description" content="<?=h($desc)?>"><meta name="robots" content="<?=$noindex?'noindex, follow':'index, follow'?>"><link rel="canonical" href="<?=h($url)?>"><meta property="og:title" content="<?=h($title)?>"><meta property="og:description" content="<?=h($desc)?>"><meta property="og:url" content="<?=h($url)?>"><meta property="og:image" content="<?=BASE?>/evidence/assets/banner.webp"><link rel="icon" href="/favicon.ico"><link rel="stylesheet" href="/evidence/assets/evidence.css?v=1.4.0"><script src="/evidence/assets/evidence.js?v=1.4.0" defer></script><script type="application/ld+json"><?=j(['@context'=>'https://schema.org','@graph'=>[['@type'=>'WebPage','name'=>$title,'description'=>$desc,'url'=>$url,'inLanguage'=>'en','isPartOf'=>['@type'=>'WebSite','name'=>'Beyond Spacetime','url'=>BASE.'/']],['@type'=>'BreadcrumbList','itemListElement'=>[['@type'=>'ListItem','position'=>1,'name'=>'Home','item'=>BASE.'/'],['@type'=>'ListItem','position'=>2,'name'=>'Evidence','item'=>BASE.ROOT]]]]])?></script><link rel="stylesheet" href="/museum/assets/crossnav.css?v=2.2.1"></head><body><a class="skip" href="#main">Skip to content</a><header><div class="nav"><a class="brand" href="/"><img src="/evidence/assets/compass.png" width="48" height="48" alt=""><span>BEYOND<span class="gold">SPACETIME</span><small>THE EXPLAINER PROJECT</small></span></a><nav aria-label="Main navigation"><?php if(\bsp_legacy_available()):?><a href="/learn/">Learn</a><?php endif;?><a href="/foundations/">Foundations</a><?php if(\bsp_legacy_available()):?><a href="/labs/">Labs</a><?php endif;?><?php if(\bsp_legacy_available()):?><a href="/explore/">Explore 3D</a><?php endif;?><a href="/evidence/" aria-current="page">Evidence</a><?php if(\bsp_legacy_available()):?><a href="/agents/">Agents</a><?php endif;?></nav><a class="arc" href="https://arcsecs.com/read-scientific-paper/">ArcSecs ↗</a></div></header><nav class="museum-crossnav" aria-label="Museum exhibits"><a href="/museum/">Museum</a><a href="/museum/search/">Search</a><a href="/foundations/">Foundations</a><a href="/evidence/" aria-current="true">Evidence</a><a href="/research/">Workspace</a><a href="/model-comparison/">Compare</a><a href="/timeline/">Timeline</a><a href="/global/">Languages</a><a href="/offline/">Offline</a><a href="/visualizations/">Visualize</a><a href="/knowledge-graph/">Graph</a><a href="/experiment-design/">Design</a><a href="/universal-time/">Time</a></nav><main class="wrap" id="main"><div class="crumb"><a href="/">Home</a> / <a href="/evidence/">Evidence</a></div><nav class="subnav" aria-label="Evidence navigation"><a href="/evidence/">Overview</a><a href="/evidence/ledger/">Evidence ledger</a><a href="/evidence/gates/">Validation gates</a><a href="/evidence/workbench/">Numerical controls</a></nav><?php }
function endpage():void{?><footer><div><strong>Beyond Spacetime</strong><p>Scientific learning companion. No new observational validation claimed.</p></div><div><a href="/evidence/catalog.json">Machine-readable catalog</a><a href="/evidence/api/">API documentation</a><a href="/evidence/sitemap.xml">Evidence sitemap</a></div><div><a href="/foundations/">Twelve foundations</a><a href="https://arcsecs.com/read-scientific-paper/">Review 6.0 ↗</a><a href="https://arcsecs.com/read-book/">Original book ↗</a></div></footer></main></body></html><?php }
function statuslabel($s):string{return corpus()['statuses'][$s];}
function card(array $r):void{?><article class="ev-card panel" data-record="<?=h($r['id'])?>"><span class="status status-<?=h($r['status'])?>"><?=h(statuslabel($r['status']))?></span><p class="kicker"><?=h($r['branch'].' · '.$r['phase'])?></p><h2><a href="/evidence/ledger/<?=h($r['id'])?>/"><?=h($r['title'])?></a></h2><p><?=h($r['finding'])?></p><p class="muted small">Review 6.0 · pp. <?=h(implode(', ',$r['pages']))?></p><a href="/evidence/ledger/<?=h($r['id'])?>/">Examine record →</a></article><?php }
function hub():void{start('Scientific Evidence Explorer','Explore evidence, conditional findings, restricted failures and seven validation gates in ArcSecs Scientific Review 6.0.',ROOT);?><section class="ev-hero"><div><span class="kicker gold">THE SCIENTIFIC EVIDENCE EXPLORER · 1.4.0</span><h1>Follow the evidence.<br>Keep the questions open.</h1><p class="lead">Discover what the research actually establishes, where candidate models fail, and what must be measured next. Every record points back to the original scientific review.</p><div class="actions"><a class="button" href="/evidence/ledger/">Explore the ledger →</a><a class="button secondary" href="/evidence/gates/">View validation gates</a></div></div><img src="/evidence/assets/banner.webp" alt="Beyond Spacetime cosmic artwork" width="960" height="412"></section><div class="ev-counts"><?php foreach([[count(records()),'Curated evidence records'],[count(corpus()['gates']),'Research validation gates'],[count(specs()),'Reproducible teaching controls']] as [$num,$label]):?><div><strong><?=$num?></strong><span><?=h($label)?></span></div><?php endforeach;?></div><section class="section"><h2>Understand the status of a claim</h2><div class="ev-grid"><?php foreach(corpus()['statuses'] as $key=>$label):?><a class="panel status-link" href="/evidence/ledger/?status=<?=h($key)?>"><span class="status status-<?=h($key)?>"><?=h($label)?></span><strong><?=count(array_filter(records(),fn($r)=>$r['status']===$key))?> records →</strong></a><?php endforeach;?></div></section><section class="section"><h2>Key research decisions</h2><div class="ev-grid"><?php foreach(['wall-crossing','escape-criterion','joint-fit'] as $id)card(records()[$id]);?></div></section><section class="panel"><h2>Original source, not a second publication</h2><p>This explorer contains original summaries of selected findings in Scientific Review 6.0. Reported external references have not been independently revalidated in this release. The complete paper and book remain on ArcSecs.</p><a href="https://arcsecs.com/read-scientific-paper/">Read the authoritative paper ↗</a></section><?php endpage();}
function ledger():void{$q=is_string($_GET['q']??null)?substr(trim($_GET['q']),0,120):'';$status=is_string($_GET['status']??null)?$_GET['status']:'';$gate=is_string($_GET['gate']??null)?$_GET['gate']:'';$branch=is_string($_GET['branch']??null)?$_GET['branch']:'';$all=records();$branches=array_unique(array_column($all,'branch'));sort($branches);$filtered=array_filter($all,fn($r)=>($status===''||$status===$r['status'])&&($gate===''||in_array($gate,$r['gates'],true))&&($branch===''||$branch===$r['branch'])&&($q===''||stripos(implode(' ',[$r['title'],$r['finding'],$r['limitation'],$r['phase'],$r['next_test']]),$q)!==false));start('Evidence ledger','Search and filter research findings, limitations and next tests.',ROOT.'ledger/',(bool)($q||$status||$gate||$branch));?><section class="intro"><span class="kicker">RESEARCH RECORDS</span><h1>Evidence ledger</h1><p class="lead">Filter by epistemic status, research branch or validation gate. Failures are preserved alongside conditional successes.</p></section><form class="panel filters" method="get" action="/evidence/ledger/"><label>Search records<input type="search" name="q" value="<?=h($q)?>" maxlength="120" placeholder="Escape, wall, timing…"></label><?php foreach(['status'=>['Status',corpus()['statuses'],$status],'branch'=>['Branch',array_combine($branches,$branches),$branch],'gate'=>['Gate',array_column(corpus()['gates'],'title','id'),$gate]] as $key=>[$label,$opts,$current]):?><label><?=h($label)?><select name="<?=$key?>"><option value="">All</option><?php foreach($opts as $v=>$t):?><option value="<?=h($v)?>" <?=$v===$current?'selected':''?>><?=h($t)?></option><?php endforeach;?></select></label><?php endforeach;?><div class="actions"><button class="button">Apply filters</button><a href="/evidence/ledger/">Reset</a></div></form><p class="muted" role="status"><?=count($filtered)?> of <?=count($all)?> records</p><div class="ev-grid"><?php foreach($filtered as $r)card($r);?></div><?php if(!$filtered):?><p class="panel">No matching records. Try removing a filter.</p><?php endif;?><section class="panel section"><h2>Compare two research records</h2><form id="compare-records" class="filters"><label>Record A<select id="record-a"><?php foreach($all as $r):?><option value="<?=h($r['id'])?>" <?=$r['id']==='fixed-gap-drag'?'selected':''?>><?=h($r['title'])?></option><?php endforeach;?></select></label><label>Record B<select id="record-b"><?php foreach($all as $r):?><option value="<?=h($r['id'])?>" <?=$r['id']==='escape-criterion'?'selected':''?>><?=h($r['title'])?></option><?php endforeach;?></select></label><button type="button" class="button secondary" id="compare-run" hidden>Compare</button></form><div id="compare-output" class="ev-grid two"></div><noscript><p>Open individual records to compare them without JavaScript.</p></noscript><script type="application/json" id="record-data"><?=j(array_values($all))?></script></section><?php endpage();}
function record_page(string $id):void{$r=records()[$id];start($r['title'],$r['finding'],ROOT.'ledger/'.$id.'/');?><section class="intro"><span class="status status-<?=h($r['status'])?>"><?=h(statuslabel($r['status']))?></span><p class="kicker"><?=h($r['branch'].' · '.$r['phase'])?></p><h1><?=h($r['title'])?></h1><p class="lead"><?=h($r['finding'])?></p></section><div class="ev-grid two"><section class="panel"><h2>What this does not establish</h2><p><?=h($r['limitation'])?></p></section><section class="panel"><h2>Next decisive test</h2><p><?=h($r['next_test'])?></p></section><section class="panel"><h2>Primary source</h2><p>Scientific Review 6.0 · <?=h($r['phase'])?> · printed pp. <?=h(implode(', ',$r['pages']))?>.</p><a href="<?=h($r['source_url'])?>">Read original scientific manuscript ↗</a></section><section class="panel"><h2>Related research gates</h2><?php foreach($r['gates'] as $g):?><a class="chip" href="/evidence/gates/#gate-<?=$g?>">Gate <?=$g?></a><?php endforeach;?><h3>Related foundations</h3><?php foreach($r['foundations'] as $f):?><a class="chip" href="/foundations/<?=h($f)?>/"><?=h(str_replace('-',' ',$f))?></a><?php endforeach;?></section></div><?php if($r['workbench']):?><div class="actions"><a class="button" href="/evidence/workbench/<?=h($r['workbench'])?>/">Run numerical control →</a></div><?php endif;?><section class="section"><h2>Related records</h2><div class="ev-grid"><?php $others=array_filter(records(),fn($a)=>$a['id']!==$id&&$a['branch']===$r['branch']);foreach(array_slice($others,0,3) as $a)card($a);?></div></section><a href="/evidence/ledger/">← All evidence</a><?php endpage();}
function gates():void{start('Seven validation gates','The original Review 6.0 validation sequence, with linked evidence and acceptance criteria.',ROOT.'gates/');?><section class="intro"><span class="kicker">RESEARCH ROADMAP · §16.3</span><h1>Seven gates to a unified model</h1><p class="lead">A gate is an acceptance condition, not a progress score. Review 6.0 does not establish completion of the unified observational program.</p></section><?php foreach(corpus()['gates'] as $g):$count=count(array_filter(records(),fn($r)=>in_array($g['id'],$r['gates'],true)));?><section class="panel gate" id="gate-<?=$g['id']?>"><div class="gate-letter"><?=$g['id']?></div><div><span class="status status-open"><?=h($g['status'])?></span><h2><?=h($g['title'])?></h2><p><strong>Deliverable:</strong> <?=h($g['deliverable'])?></p><p><strong>Pass condition:</strong> <?=h($g['pass_condition'])?></p><a href="/evidence/ledger/?gate=<?=$g['id']?>"><?=$count?> linked records →</a></div></section><?php endforeach;?><?php endpage();}
function chart(array $r):void{$rows=$r['rows'];$xmin=$rows[0][0];$xmax=end($rows)[0];$ymin=0.;$ymax=0.;foreach($rows as $row)foreach(array_slice($row,1) as $y){$ymin=min($ymin,$y);$ymax=max($ymax,$y);}if($ymax===$ymin)$ymax+=1;$x=fn($v)=>60+($v-$xmin)/($xmax-$xmin)*590;$y=fn($v)=>220-($v-$ymin)/($ymax-$ymin)*190;?><figure class="ev-chart"><svg viewBox="0 0 680 260" role="img" aria-label="<?=h(implode(', ',$r['series']).' versus '.$r['x'])?>"><?php for($i=0;$i<=4;$i++):$Y=30+$i*47.5;$X=60+$i*147.5;?><line x1="60" x2="650" y1="<?=$Y?>" y2="<?=$Y?>" class="gridline"/><text x="54" y="<?=$Y+4?>" text-anchor="end"><?=h(n($ymax-($ymax-$ymin)*$i/4))?></text><text x="<?=$X?>" y="240" text-anchor="middle"><?=h(n($xmin+($xmax-$xmin)*$i/4))?></text><?php endfor;foreach($r['series'] as $i=>$v):?><polyline class="curve c<?=$i?>" points="<?=h(implode(' ',array_map(fn($a)=>sprintf('%.2f,%.2f',$x($a[0]),$y($a[$i+1])),$rows)))?>"/><?php endforeach;?></svg><figcaption><?=h($r['x'])?> · <?php foreach($r['series'] as $i=>$v):?><span class="legend c<?=$i?>"><?=h($v)?></span><?php endforeach;?></figcaption></figure><?php }
function workbench(?string $id=null):void{if($id===null){start('Numerical evidence workbench','Three independently executable educational controls tied to Review 6.0.',ROOT.'workbench/');?><section class="intro"><h1>Test the evidence</h1><p class="lead">Recompute three restricted controls from the review. These are original implementations of the stated equations, not a rerun of the source simulation archive.</p></section><div class="ev-grid"><?php foreach(specs() as $k=>$s):?><article class="panel"><h2><?=h($s['title'])?></h2><p><?=h($s['description'])?></p><a href="/evidence/workbench/<?=$k?>/">Open control →</a></article><?php endforeach;?></div><?php endpage();return;}$s=specs()[$id];$post=($_SERVER['REQUEST_METHOD']??'GET')==='POST';$err='';try{$r=calc($id,$post?($_POST['p']??[]):[]);}catch(InvalidArgumentException|TypeError $e){http_response_code(422);$err='Invalid parameters. Defaults displayed.';$r=calc($id);}start($s['title'],$s['description'],ROOT.'workbench/'.$id.'/',$post);?><section class="intro"><span class="kicker">NUMERICAL EVIDENCE</span><h1><?=h($s['title'])?></h1><p class="lead"><?=h($s['description'])?></p></section><div class="work-grid"><section class="panel"><h2>Parameters</h2><form method="post" action="/evidence/workbench/<?=$id?>/"><?php foreach($s['params'] as $k=>$p):?><label class="field"><?=h($p[0])?><input type="number" name="p[<?=$k?>]" min="<?=$p[2]?>" max="<?=$p[3]?>" step="any" value="<?=h($r['parameters'][$k])?>" required><small><?=h($p[2].' to '.$p[3])?></small></label><?php endforeach;?><button class="button">Recalculate</button> <a href="/evidence/workbench/<?=$id?>/">Reset</a></form><?php if($err):?><p role="alert"><?=h($err)?></p><?php endif;?></section><section class="panel"><h2>Calculated evidence</h2><div class="ev-metrics"><?php foreach($r['metrics'] as $m):?><div><small><?=h($m['label'])?></small><strong><?=h(n($m['value']).' '.$m['unit'])?></strong></div><?php endforeach;?></div><?php chart($r);?><p><?=h($r['limitation'])?></p><div class="actions"><button type="button" class="button secondary" id="export-json" hidden>Export JSON</button><button type="button" class="button secondary" id="export-csv" hidden>Export CSV</button></div><details><summary>Numerical samples (first 10 and final)</summary><div class="table-scroll"><table><thead><tr><?php foreach(array_merge([$r['x']],$r['series']) as $v):?><th scope="col"><?=h($v)?></th><?php endforeach;?></tr></thead><tbody><?php foreach(array_merge(array_slice($r['rows'],0,10),[end($r['rows'])]) as $row):?><tr><?php foreach($row as $v):?><td><?=h(n($v))?></td><?php endforeach;?></tr><?php endforeach;?></tbody></table></div></details><script type="application/json" id="result-data"><?=j($r)?></script></section></div><section class="panel section"><h2>Interpretation and source</h2><a href="/evidence/ledger/<?=h($s['record'])?>/">Read the associated evidence record →</a></section><?php endpage();}
